import Link from "next/link";
import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, Wave 7 rollout.
 *
 * CONTENT FIX, not just a design swap: this route's family is "ark" (ARK:
 * Survival EVOLVED, the original 2015 game, Steam app 376030), but the
 * previous version of this page had its entire copy — title, hero, FAQ,
 * steps — swapped with ARK: Survival ASCENDED content (Studio Wildcard's
 * separate UE5 remake, family "arkasa", its own page at
 * /ark-survival-ascended-server-hosting). That was a leftover copy-paste bug,
 * confirmed by the comment at the top of ark-survival-ascended-server-hosting
 * /page.tsx ("the original ARK: Survival Evolved, which stays live at
 * /ark-server-hosting"). This rewrite is genuinely about Survival Evolved.
 *
 * This also converts the page from self-managed VPS framing (customer SSHes
 * in and runs SteamCMD themselves) to the real one-click managed hosting
 * that just went live (prisma/seed-wave7-games.ts — real OsTemplate +
 * GamePlan rows, confirmed orderable in the deploy wizard).
 *
 * PREVIEW_GAMES.ark was authored directly from those real seeded GamePlan
 * rows (8 GB/20 slots $14.99, 16 GB/50 slots $27.99 popular, 32 GB/100 slots
 * $49.99) — no price override needed here.
 *
 * Art: family "ark"'s art slug is "ark-asa" (see lib/games.ts GAME_ART_SLUG).
 * Confirmed via that file's own comment that "ark-asa" actually contains
 * genuine ARK: Survival EVOLVED key art despite the confusing slug name (a
 * separate, already-documented mislabeling issue) — so the art is correct
 * for this family and no art change was made alongside this copy fix.
 *
 * FAQ + related-links sections below follow the same pattern as
 * rust-server-hosting/page.tsx, since GameLandingCombined doesn't render its
 * own FAQ/related sections.
 */

export const metadata: Metadata = {
  title: "ARK: Survival Evolved Server Hosting — Instant Setup",
  description:
    "Managed ARK: Survival Evolved server hosting from $14.99/mo. Full FTP access, your own admin password, and instant setup on our low-latency Singapore or Germany network.",
  alternates: { canonical: "/ark-server-hosting" },
  openGraph: {
    type: "article",
    title: "ARK: Survival Evolved Server Hosting — Instant Setup",
    description:
      "Managed ARK: Survival Evolved hosting: full FTP access, your own admin password, and instant setup on our low-latency Singapore or Germany network. From $14.99/mo.",
    url: `${APP_URL}/ark-server-hosting`,
  },
};

const GAME = PREVIEW_GAMES.ark;

const FAQ = [
  {
    q: "Is this ARK: Survival Evolved or ARK: Survival Ascended?",
    a: "This page is the original ARK: Survival Evolved (2015, Steam app 376030). Survival Ascended is Studio Wildcard's separate Unreal Engine 5 remake, hosted on its own plans — see our ARK: Survival Ascended hosting page if that's the one you want.",
  },
  {
    q: "How much RAM does an ARK: Survival Evolved server need?",
    a: "8 GB comfortably runs a small tribe on a single map, 16 GB is the recommended baseline for a fuller 50-slot tribe server, and 32 GB gives a busy multi-tribe alliance server room to breathe. Our three plans map directly to those tiers.",
  },
  {
    q: "Can I install mods?",
    a: "Yes. Full FTP file access lets you upload mods and edit GameUserSettings.ini and Game.ini directly to tune taming rates, difficulty, and mod lists — no host-imposed limits.",
  },
  {
    q: "What ports does ARK: Survival Evolved use?",
    a: "The game ports are 7777 and 7778 (UDP), with an RCON/query port on 27020 (TCP). On a managed Nxeon server those are opened for you and the connect details are provided automatically.",
  },
  {
    q: "Is this managed, or do I set it up myself?",
    a: "Fully managed one-click hosting — no SteamCMD or server install to run yourself. Order a plan and it's provisioned and online in minutes, with your admin password ready to set and full FTP access from the start.",
  },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "ARK: Survival Ascended hosting", href: "/ark-survival-ascended-server-hosting" },
  { label: "Conan Exiles server hosting", href: "/conan-exiles-server-hosting" },
  { label: "Gaming VPS", href: "/gaming-vps" },
  { label: "Pricing", href: "/pricing" },
];

export default function ArkServerHostingPage() {
  return (
    <>
      <FaqJsonLd items={FAQ} />
      <ProductOffersJsonLd
        name="Nxeon ARK: Survival Evolved Server Hosting"
        description={GAME.deck}
        url={`${APP_URL}/game-servers`}
        offers={GAME.plans.map((p) => ({
          name: `${GAME.name} ${p.tier} (${p.ram})`,
          price: parseFloat(p.price.replace(/[^0-9.]/g, "")),
        }))}

