import type { Metadata } from "next";
import { MigrateFromPageLayout } from "@/components/marketing/MigrateFromPageLayout";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const metadata: Metadata = {
  title: "Move from Hostinger to Nxeon — Free Migration",
  description:
    "Moving off Hostinger? Nxeon scans your server over SSH, auto-detects your files, databases, Docker and apps, and brings your whole stack up on Nxeon — no downtime on Hostinger, no DB passwords, free.",
  alternates: { canonical: "/migrate-from-hostinger" },
  openGraph: {
    type: "article",
    title: "Move from Hostinger to Nxeon — Free Migration",
    description:
      "One click scans your Hostinger server, detects your whole stack, and brings it up running on Nxeon. No downtime on your old server. Free.",
    url: `${APP_URL}/migrate-from-hostinger`,
  },
  twitter: {
    card: "summary_large_image",
    title: "Move from Hostinger to Nxeon — Free Migration",
    description:
      "We scan your Hostinger server, detect everything, and bring your whole stack up running on Nxeon. No DB passwords, no downtime, free.",
  },
};

// Pricing on this page is DB-fed via MigrateFromPageLayout — see lib/vps-price-band.ts pattern.
export const dynamic = "force-dynamic";

const REASONS = [
  "A broad consumer hosting suite (shared hosting, website builder, email) where VPS is one product among many",
  "hPanel and optional add-on panels rather than a single unmanaged, root-first dashboard",
  "Plans and pricing spread across many tiers and terms, which can make comparing the real monthly cost more work",
  "Game-server hosting is a separate product line rather than built into the same VPS dashboard flow",
];

export default function MigrateFromHostinger() {
  return <MigrateFromPageLayout provider="Hostinger" providerSlug="hostinger" reasons={REASONS} />;
}

